package com.profa.notification;import jakarta.persistence.*;import java.time.*;import java.util.*;@Entity @Table(name="notifications")public class Notification{@Id@GeneratedValue(strategy=GenerationType.UUID)UUID id;UUID userId;String type;String title;String body;String link;boolean read=false;Instant createdAt=Instant.now();public UUID getId(){return id;}public UUID getUserId(){return userId;}public void setUserId(UUID v){userId=v;}public String getType(){return type;}public void setType(String v){type=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getBody(){return body;}public void setBody(String v){body=v;}public String getLink(){return link;}public void setLink(String v){link=v;}public boolean isRead(){return read;}public void setRead(boolean v){read=v;}public Instant getCreatedAt(){return createdAt;}}